package com.networkmonitorpro.ui; import android.os.*;import android.view.*;import android.widget.*;import androidx.fragment.app.*;import androidx.lifecycle.*;import androidx.recyclerview.widget.*;import com.networkmonitorpro.R;import com.networkmonitorpro.ui.adapter.HistoryAdapter;import com.networkmonitorpro.ui.viewmodel.MainViewModel; public class NotifierFragment extends Fragment{ String[] opts={"5G Available","4G Available","WiFi Connected","Internet Lost","Signal Weak","Signal Improved","Network Switched"}; public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){return i.inflate(R.layout.fragment_notifier,c,false);} public void onViewCreated(View v,Bundle b){MainViewModel m=new ViewModelProvider(requireActivity()).get(MainViewModel.class); LinearLayout box=v.findViewById(R.id.settingsContainer); for(String o:opts){Switch s=new Switch(requireContext());s.setText(o);s.setTextColor(0xffffffff);s.setChecked(true);box.addView(s);} HistoryAdapter a=new HistoryAdapter(); RecyclerView rv=v.findViewById(R.id.historyList);rv.setLayoutManager(new LinearLayoutManager(requireContext()));rv.setAdapter(a); m.notifications.all().observe(getViewLifecycleOwner(),a::submit); EditText f=v.findViewById(R.id.filter); f.setOnEditorActionListener((tv,id,e)->{m.notifications.search(tv.getText().toString()).observe(getViewLifecycleOwner(),a::submit);return false;});} }
